import { userMemberCard, memberRecord, memberCardStatus } from "@/api/user";
import { mapState } from "vuex";

export default {
    name: "card",
    data() {
        return {
            columns1: [
                {
                    title: "编号",
                    key: "id",
                    minWidth: 100
                },
                {
                    title: "卡号",
                    key: "card_number",
                    minWidth: 100
                },
                {
                    title: "密码",
                    key: "card_password",
                    minWidth: 100
                },
                {
                    title: "领取人名称",
                    key: "username",
                    minWidth: 100
                },
                {
                    title: "领取人电话",
                    key: "phone",
                    minWidth: 100
                },
                {
                    title: "领取时间",
                    key: "use_time",
                    minWidth: 100
                },
                {
                    title: "是否激活",
                    slot: "status",
                    minWidth: 100
                }
            ],
            data1: [],
            loading: false,
            total: 0,
            table: {
                page: 1,
                limit: 15,
                card_number: "",
                phone: "",
                is_use: ""
            }
        };
    },
    computed: {
        ...mapState("media", ["isMobile"]),
        labelWidth() {
            return this.isMobile ? undefined : 75;
        },
        labelPosition() {
            return this.isMobile ? "top" : "right";
        }
    },
    created() {
        this.getMemberCard();
    },
    methods: {
        onchangeIsShow(row){
            let data = {
                card_id: row.id,
                status: row.status
            };
            memberCardStatus(data).then(res=>{
                this.$Message.success(res.msg);
                this.getMemberCard();
            }).catch(err=>{
                this.$Message.error(err.msg);
            })
        },
        getMemberCard() {
            this.loading = true;
            userMemberCard(this.$route.params.id, this.table)
                .then(res => {
                    this.loading = false;
                    this.data1 = res.data.list;
                    this.total = res.data.count;
                })
                .catch(err => {
                    this.loading = false;
                    this.$Message.error(err.msg);
                });
        },
        // 搜索
        formSubmit() {
            this.table.page = 1;
            this.getMemberCard();
        },
        // 分页
        pageChange(index) {
            this.table.page = index;
            this.getMemberCard();
        }
    }
};
